insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g78_health_v1'
from (values
('115.27.b.1',3,'Which body system carries oxygen-rich blood to the cells of the body?','["circulatory system", "digestive system", "nervous system", "skeletal system"]'::jsonb,0,'The heart and blood vessels circulate blood.','original'),
('115.27.b.1',3,'Your teen body relies on the nervous system mainly to...','["break food into nutrients", "send messages between the brain and the body", "fight infection with white blood cells only", "support the body''s frame"]'::jsonb,1,'Nerves carry signals, so the system controls reactions and thinking.','original'),
('115.27.b.2.A',3,'A teen with a bad earache and no doctor at home could get medical care at a...','["movie theater", "bus depot", "community clinic or urgent care center", "public library"]'::jsonb,2,'Clinics and urgent care provide care in a community.','original'),
('115.27.b.2.A',3,'Which community resource is best for getting vaccines at a low cost?','["a post office", "a shoe store", "a bowling alley", "a county public health department"]'::jsonb,3,'Health departments often give low-cost vaccines.','original'),
('115.27.b.2.B',3,'If a classmate has a seizure, a helpful action is to...','["stay calm, time it, and keep the person safe on their side", "hold their arms down", "pour water on their face", "put a spoon in their mouth"]'::jsonb,0,'Do not restrain or put objects in the mouth; protect and time the seizure.','original'),
('115.27.b.2.B',3,'Using health information to help a friend with diabetes could include...','["ignoring their supplies", "learning the signs of low or high blood sugar", "telling them to skip all meals", "joking about their condition"]'::jsonb,1,'Knowing the signs allows you to get help fast.','original'),
('115.27.b.2.C',3,'A teen cannot afford a health checkup. Which is a helpful way to overcome this barrier?','["avoid all doctors forever", "wait until it hurts a lot", "ask a counselor about free or low-cost clinics", "search for random cures in a comment section"]'::jsonb,2,'Resources can help overcome cost barriers.','original'),
('115.27.b.2.C',3,'Which is a barrier to solving a health problem?','["knowing where the clinic is", "having a reliable ride to an appointment", "having a trusted adult nearby", "being embarrassed to ask for help"]'::jsonb,3,'Embarrassment and fear keep people from care.','original'),
('115.27.b.2.D',3,'Lyme disease is spread to people mainly by the bite of an infected...','["tick", "flea on a dog''s tail only", "mosquito", "housefly"]'::jsonb,0,'Blacklegged ticks carry the bacteria.','original'),
('115.27.b.2.D',3,'West Nile virus is usually spread to people by...','["shaking hands", "mosquito bites", "eating cooked food", "tick bites"]'::jsonb,1,'Infected mosquitoes spread West Nile virus.','original'),
('115.27.b.3.A',3,'A student feels their stomach tighten before a test and notices the thought ''I will fail.'' Identifying the thought and the feeling helps them to...','["avoid ever taking tests", "blame a classmate", "understand what is causing the emotion", "ignore the feeling forever"]'::jsonb,2,'Naming thoughts and feelings is the first step to managing them.','original'),
('115.27.b.3.A',3,'Which statement shows a student identifying an emotion in themselves?','["''Whatever, nothing matters.''", "''You made me feel this way on purpose.''", "''Everyone is against me.''", "''I am frustrated because I lost my project file.''"]'::jsonb,3,'Naming the emotion and its cause shows self-awareness.','original'),
('115.27.b.3.B',3,'According to the thought-feeling-behavior link, changing how you think about a stressful event can change how you...','["feel and act", "grow taller", "see colors", "digest food"]'::jsonb,0,'Thoughts shape feelings, and feelings shape actions.','original'),
('115.27.b.3.B',3,'Which technique can help manage anger in a healthy way?','["yelling until the other person leaves", "taking slow, deep breaths before responding", "breaking something nearby", "spreading rumors online"]'::jsonb,1,'Calming the body gives you time to choose a response.','original'),
('115.27.b.3.C',3,'Positive social groups can improve mental health because they...','["push members to ignore safety", "demand secrecy about everything", "provide support, belonging and encouragement", "isolate members from their families"]'::jsonb,2,'Healthy groups support well-being.','original'),
('115.27.b.3.C',3,'A friend group pressures a teen to skip class. This peer influence is...','["positive", "a school rule", "required by law", "negative"]'::jsonb,3,'Encouraging risky or harmful behavior is negative peer influence.','original'),
('115.27.b.3.D',3,'Perspective-taking in a friendship means...','["trying to understand how the other person sees the situation", "assuming you are always right", "predicting that they will argue", "refusing to listen"]'::jsonb,0,'Understanding others builds healthy relationships.','original'),
('115.27.b.3.D',3,'Which sentence is an effective ''I-message'' for communicating in a friendship?','["''You always ruin everything.''", "''I feel hurt when plans change without telling me.''", "''Never talk to me again.''", "''Everyone knows you are selfish.''"]'::jsonb,1,'I-messages describe your feelings without attacking.','original'),
('115.27.b.3.E',3,'Two classmates disagree about a group project plan. Comparing their perspectives is useful because it can...','["prove one person is worthless", "cancel the project", "show common ground and differences", "end all communication"]'::jsonb,2,'Seeing both views helps solve problems.','original'),
('115.27.b.3.E',3,'Which question best helps someone understand another person''s perspective?','["''Don''t you know I''m right?''", "''Why can''t you be normal?''", "''Who asked you?''", "''Can you tell me how you see this?''"]'::jsonb,3,'Open questions invite the other view.','original'),
('115.27.b.3.F',3,'In peer mediation, the mediator''s job is to...','["help both sides talk and find a solution they agree on", "punish the louder student", "take one side", "decide who is the winner"]'::jsonb,0,'Mediators stay neutral and guide the talk.','original'),
('115.27.b.3.F',3,'Which is a conflict resolution skill?','["walking away without a word and posting about it", "listening without interrupting", "name-calling", "raising your voice"]'::jsonb,1,'Active listening reduces conflict.','original'),
('115.27.b.4.A',3,'Which is an external factor that can influence self-esteem?','["the number of bones in the body", "a person''s own genetic code only", "messages from social media and peers", "the size of one''s shoes"]'::jsonb,2,'Social feedback shapes how we see ourselves.','original'),
('115.27.b.4.A',3,'An internal factor that can influence a teen''s self-esteem is...','["a teacher''s grade", "a viral post", "a classmate''s comment", "self-talk, or what they tell themselves"]'::jsonb,3,'Thoughts about oneself come from within.','original'),
('115.27.b.4.B',3,'A strong long-term personal goal is one that is...','["specific, realistic and has steps with deadlines", "impossible by design", "vague and without a plan", "chosen by a stranger"]'::jsonb,0,'Clear steps make goals reachable.','original'),
('115.27.b.4.B',3,'Breaking a big goal such as ''save for a laptop'' into smaller steps is called...','["delaying forever", "setting short-term goals toward a long-term goal", "avoiding goals", "random guessing"]'::jsonb,1,'Small steps build progress.','original'),
('115.27.b.4.C',3,'When planning life goals such as graduating, a teen should also consider...','["nothing about money", "only what friends say", "the cost and the financial impact of reaching the goal", "only what looks exciting"]'::jsonb,2,'Financial impact is part of planning.','original'),
('115.27.b.4.C',3,'Which choice makes a personal life goal more likely to succeed?','["keeping it secret and forgetting it", "never revising it", "copying a friend''s goals exactly", "writing it down and checking progress"]'::jsonb,3,'Written goals with check-ins improve follow-through.','original'),
('115.27.b.4.D',3,'A good decision-making step before choosing is to...','["think about possible consequences for yourself and others", "do what the group does without asking", "act at once without thinking", "flip a coin for every choice"]'::jsonb,0,'Considering consequences promotes health.','original'),
('115.27.b.4.D',3,'Which decision-making skill helps protect family and community mental health?','["keeping every problem secret", "asking a trusted adult for advice on a hard choice", "ignoring warning signs", "blaming others"]'::jsonb,1,'Seeking advice leads to better decisions.','original'),
('115.27.b.5.A',3,'During adolescence, the part of the brain that handles planning and impulse control...','["stops working", "is fully finished", "is still developing", "turns off during school"]'::jsonb,2,'The prefrontal cortex keeps maturing into early adulthood.','original'),
('115.27.b.5.A',3,'Because the adolescent brain is still developing, teens may be more likely to...','["lose the ability to learn", "stop growing at age 12", "never feel strong emotions", "act on emotions and take risks"]'::jsonb,3,'Emotion centers can outpace judgment.','original'),
('115.27.b.5.B',3,'Constant loud noise at home or school can harm mental health by increasing...','["stress and difficulty concentrating", "height", "bone density", "vision color"]'::jsonb,0,'Environmental noise contributes to stress.','original'),
('115.27.b.5.B',3,'Which environmental influence can affect a person''s well-being?','["a short walk in a clean park", "polluted air or unsafe water", "a favorite song", "a new pencil"]'::jsonb,1,'Air and water quality influence health.','original'),
('115.27.b.5.C',3,'A teen who experienced a frightening event as a child and still feels upset should...','["pretend nothing happened", "keep it hidden forever", "talk with a counselor or trusted adult", "use substances to cope"]'::jsonb,2,'Support helps people process trauma.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Health Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
